// Secret stays in the n8n environment (RETELL_API_KEY). Never paste it into this file.
const item = $input.first().json;
const headers = item.headers || {};
const body = item.body && typeof item.body === 'object' ? item.body : item;
let webhookSecret = '';
let fromNumber = '';
let inboundId = 'agent_dc1a3df8b89476e4868363ee98';
let outboundId = 'agent_2603c7b2c919d2677273e30634';
let apiKeySet = false;
try {
  webhookSecret = $env.N8N_WEBHOOK_SECRET || $env.PROXY_SHARED_SECRET || '';
  fromNumber = $env.RETELL_FROM_NUMBER || '';
  if ($env.RETELL_INBOUND_AGENT_ID) inboundId = $env.RETELL_INBOUND_AGENT_ID;
  if ($env.RETELL_OUTBOUND_AGENT_ID) outboundId = $env.RETELL_OUTBOUND_AGENT_ID;
  apiKeySet = Boolean($env.RETELL_API_KEY);
} catch (err) {
  throw new Error('n8n is blocking environment access. Allow $env for RETELL_API_KEY, or run server/retell-proxy.mjs instead.');
}
if (!apiKeySet) {
  throw new Error('Set RETELL_API_KEY in the n8n environment. Use the key named bdhousing-voice. Do not paste it into this workflow.');
}
if (webhookSecret) {
  const got = headers['x-n8n-secret'] || headers['x-proxy-secret'] || '';
  if (got !== webhookSecret) throw new Error('Send the matching X-N8N-Secret header.');
}
const channel = body.channel === 'phone' ? 'phone' : 'web';
const agentChoice = body.agent === 'inbound' ? 'inbound' : 'outbound';
const vars = {};
const source = body.retell_llm_dynamic_variables && typeof body.retell_llm_dynamic_variables === 'object' ? body.retell_llm_dynamic_variables : {};
for (const [key, value] of Object.entries(source)) {
  if (value != null) vars[key] = String(value);
}
for (const key of ['customer_name', 'preferred_language', 'property_interest', 'call_purpose', 'phone']) {
  if (body[key] != null && vars[key] == null) vars[key] = String(body[key]);
}
const metadata = Object.assign({ source: 'bdhousing-n8n', workspace: 'BDHousing', org_id: 'org_b6zBp6LIqhl3aV7n', agent: agentChoice }, body.metadata || {});
if (channel === 'phone') {
  if (body.consent_granted !== true) throw new Error('consent_granted true is required before a phone call.');
  if (!fromNumber) throw new Error('Set RETELL_FROM_NUMBER after you buy or import a Retell number and bind the outbound agent. Web calls do not need it.');
  const to = String(body.to_number || '').replace(/[\s()-]/g, '');
  if (!/^\+[1-9]\d{7,14}$/.test(to)) throw new Error('to_number must be E.164, for example +8801711223344.');
  return [{ json: { url: 'https://api.retellai.com/v2/create-phone-call', payload: { from_number: fromNumber, to_number: to, override_agent_id: outboundId, override_agent_version: 'latest_published', retell_llm_dynamic_variables: vars, metadata } } }];
}
return [{ json: { url: 'https://api.retellai.com/v3/create-web-call', payload: { agent_id: agentChoice === 'inbound' ? inboundId : outboundId, agent_version: 'latest_published', retell_llm_dynamic_variables: vars, metadata } } }];

const result = $input.first().json;
if (result.error) {
  const err = result.error;
  throw new Error(err.message || err.description || JSON.stringify(err));
}
if (!result.call_id && !result.access_token) {
  throw new Error(result.error_message || result.message || 'Retell did not return a call.');
}
return [{ json: result }];
